/* Discours à jouer : texte qui défile (prompteur) avec silences chronométrés. Partagé plateforme et Studio. */
(function(){
var DATA={"sections":[{"id":"hom","t":"Hommage et adieu","d":"Dire l’émotion sans la jouer."},{"id":"mot","t":"Motiver et mobiliser","d":"Entraîner un groupe par le rythme et l’énergie."},{"id":"con","t":"Convaincre","d":"Défendre une idée avec méthode."},{"id":"exp","t":"Expliquer un sujet","d":"Rendre un sujet clair en trois étapes, avec une image."},{"id":"rem","t":"Remercier","d":"Reconnaître les autres avec justesse."},{"id":"pro","t":"Se présenter et pitcher","d":"Être clair, bref et mémorable."},{"id":"tra","t":"Oser et gérer le trac","d":"Parler même quand on n’est pas prêt."},{"id":"voi","t":"Voix, souffle et corps","d":"Exercices à jouer pour travailler un geste à la fois."},{"id":"com","t":"Débat, questions et critiques","d":"Garder la maîtrise quand on te questionne ou te contredit."},{"id":"spe","t":"Moments de vie","d":"Toast, anniversaire, inauguration, remise de diplôme."}],"discours":[{"id":"d1","s":"hom","n":1,"t":"Au revoir, Madame Rabe","but":"Faire ressentir une émotion en ralentissant et en te taisant, sans appuyer.","appris":[["L18","Débit et pauses"],["L19","Intonation et émotion"],["L14","Raconter des histoires"]],"controle":["J’ai tenu chaque silence sans le combler.","Ma voix a baissé sur « Mais je tremble debout ».","J’ai regardé quelqu’un sur « Merci, Madame Rabe »."],"l":["[Regardez l’assistance. Silence de 3 secondes.]","Mesdames, Messieurs,","[Respirez.]","Je ne sais pas faire les adieux.","[Pause.]","Alors je vais vous raconter un matin.","[Ralentissez.]","Un matin de septembre. J’avais sept ans. Je n’osais pas lever la main.","Madame Rabe s’est arrêtée devant mon banc. Elle n’a rien dit.","[Pause.]","Elle a simplement posé un crayon devant moi.","Un crayon taillé. Pour moi.","[Silence de 2 secondes.]","Ce jour-là, j’ai compris qu’on peut donner du courage sans faire de bruit.","[Voix plus basse.]","Trente ans plus tard, je parle devant vous. Et je tremble encore un peu.","[Pause.]","Mais je tremble debout.","[Silence de 3 secondes.]","Merci, Madame Rabe.","[Regardez-la. Pause longue.]","Pour le crayon. Et pour tout ce qu’il y avait dedans.","[Baissez la tête. Silence final de 3 secondes.]"]},{"id":"d2","s":"hom","n":2,"t":"Le dernier jour","but":"Conclure un adieu par une formule qu’on retient, au lieu de s’étirer.","appris":[["L9","La conclusion inoubliable"],["L15","Citations et formules mémorables"],["L18","Débit et pauses"]],"controle":["Ma phrase finale était courte et je l’ai dite lentement.","Je n’ai pas ajouté un « voilà » après le dernier mot.","J’ai gardé le silence final jusqu’au bout."],"l":["[Souriez. Regardez la salle.]","Chers collègues,","Quatre ans dans la même équipe, ça laisse des habitudes.","Le café trop fort de Samir.","[Pause.]","Les réunions de dix minutes qui en durent soixante.","[Pause.]","Et ce bureau, près de la fenêtre, où j’ai appris plus que dans n’importe quel cours.","[Ralentissez.]","On croit qu’on quitte un lieu.","[Pause.]","En réalité, on quitte des gens.","[Silence de 2 secondes.]","Mais les gens, eux, ne s’effacent pas d’un badge qu’on rend.","[Pause.]","Je repars avec trois choses : une méthode, des amis, et l’envie de bien faire.","[Montez légèrement la voix.]","Alors ce n’est pas un adieu. C’est un à bientôt, avec de l’expérience en plus.","[Levez votre verre ou vos mains. Pause.]","Merci.","[Silence final de 3 secondes.]"]},{"id":"d3","s":"mot","n":2,"t":"Avant le match","but":"Donner de l’élan à un groupe avec des répétitions et un volume qui monte.","appris":[["L13","Le rythme et la musicalité"],["L12","Les figures de style essentielles"],["L17","Volume et projection"]],"controle":["J’ai marqué l’anaphore « Nous » à chaque reprise.","Mon volume a monté de la 1re à la dernière phrase.","J’ai fini fort, puis je me suis tu."],"l":["[Voix posée. Regardez chaque visage.]","Écoutez-moi.","[Pause.]","Nous n’avons pas le plus grand budget.","Nous n’avons pas le plus de temps.","Nous n’avons pas la plus grande équipe.","[Pause. Baissez la voix.]","Mais nous avons autre chose.","[Montez un peu.]","Nous avons travaillé quand personne ne regardait.","Nous avons recommencé quand ça ne marchait pas.","Nous avons tenu quand c’était plus simple d’abandonner.","[Pause.]","Alors ce soir, nous ne jouons pas pour prouver.","[Plus fort.]","Nous jouons parce que nous sommes prêts.","[Pause.]","Prêts à courir. Prêts à tomber. Prêts à nous relever.","[Pleine voix, bras ouverts.]","Ensemble. Maintenant. Allons-y !","[Silence de 2 secondes.]"]},{"id":"d4","s":"mot","n":3,"t":"Il est encore temps","but":"Mobiliser des gens autour d’une cause : problème, espoir, appel à agir.","appris":[["L3","Les cinq canons de la rhétorique"],["L2","Ethos, Pathos, Logos, Kairos"],["L19","Intonation et émotion"],["L9","La conclusion inoubliable"]],"controle":["J’ai nommé le problème avec un chiffre, pas seulement avec une émotion.","Ma voix est montée entre l’espoir et l’appel à agir.","J’ai terminé par une action précise que chacun peut faire."],"l":["[Regardez la salle. Silence de 2 secondes.]","Mesdames, Messieurs,","Chaque année, notre rivière perd un peu de sa vie.","[Pause.]","Cette année, c’est un poisson sur deux.","[Silence de 2 secondes.]","Je ne vous dis pas cela pour vous accabler.","[Respirez.]","Je vous le dis parce que je me souviens de cette rivière, enfant. Elle chantait.","[Voix plus douce.]","Et elle chante encore. Écoutez : elle chante encore.","[Pause.]","Voilà pourquoi je ne crois pas qu’il soit trop tard.","[Montez la voix.]","Il est encore temps de nettoyer ses rives.","Il est encore temps de changer ce que nous y jetons.","Il est encore temps de lui rendre ce qu’elle nous a donné.","[Pause.]","Samedi, huit heures, au pont.","Apportez des gants. Apportez un voisin.","[Pleine voix.]","Et rendons-lui sa voix !","[Silence final de 3 secondes.]"]},{"id":"d5","s":"con","n":2,"t":"Parler le premier","but":"Défendre une idée : affirmation, raison, preuve, puis réfuter sans écraser.","appris":[["LX1","Construire une idée : affirmation, raison, preuve"],["LX2","Les connecteurs : la colle du discours"],["LA4","Réfuter sans écraser"]],"controle":["J’ai dit clairement mon affirmation avant ma raison.","J’ai marqué un silence après chaque preuve.","J’ai reconnu l’objection avant d’y répondre."],"l":["[Posture droite. Regard fixe.]","Je veux défendre une idée simple : en réunion, il vaut mieux parler le premier.","[Pause.]","D’abord, parce que le premier fixe le cadre.","[Pause.]","Par exemple, quand je propose un horaire de réunion, les autres discutent presque toujours autour de mon horaire, pas du leur.","[Silence de 2 secondes.]","Ensuite, parce que le premier choisit les mots.","Celui qui dit « risque » fait penser au danger. Celui qui dit « chance » fait penser à l’avenir.","[Pause.]","On me répondra : « Parler le premier, c’est risquer de se tromper. »","[Hochez la tête.]","C’est vrai, et c’est une crainte légitime.","Mais une erreur dite tôt se corrige tôt. Une idée gardée pour soi ne corrige rien.","[Pause.]","Donc, la prochaine fois, ne demandez pas : « Suis-je prêt ? »","[Regardez quelqu’un.]","Demandez-vous : « Qu’est-ce que je peux poser sur la table ? »","[Silence final de 3 secondes.]"]},{"id":"d6","s":"rem","n":1,"t":"Merci à ceux qu’on n’applaudit pas","but":"Remercier avec des détails précis, pour que chacun se sente vu.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L37","L’humilité et l’écoute"],["L23","Le regard"]],"controle":["J’ai regardé chaque personne nommée.","J’ai donné un détail précis, pas un « merci pour tout ».","J’ai gardé mon sourire pendant le silence."],"l":["[Souriez. Regardez la salle.]","Ce prix porte mon nom.","[Pause.]","Mais il appartient à d’autres.","[Ralentissez.]","À Awa, qui est arrivée la première chaque matin, pour que tout soit prêt.","[Regardez Awa.]","À Paul, qui a refait trois fois le même document sans soupirer.","[Regardez Paul.]","À ma famille, qui a dîné sans moi plus souvent qu’elle ne l’aurait voulu.","[Pause.]","On applaudit celui qui monte sur scène.","[Silence de 2 secondes.]","Mais une scène tient debout grâce à des gens qu’on ne voit pas.","[Voix posée.]","Alors, ce soir, je ne vous demande qu’une chose.","[Pause.]","Applaudissez-les à ma place.","[Reculez d’un pas. Silence de 3 secondes.]"]},{"id":"d7","s":"pro","n":3,"t":"Un projet en une minute","but":"Présenter un projet en 60 secondes : accroche, problème, solution, demande.","appris":[["LB1","Réunion, entretien, pitch"],["L8","L’introduction parfaite"],["L47","Répondre aux questions : PREP et STAR"]],"controle":["Ma phrase d’accroche est partie sans « euh ».","J’ai fini par une demande claire et chiffrée.","J’ai tenu environ une minute."],"l":["[Debout. Respirez. Souriez.]","Bonjour. Une question : combien de temps avez-vous perdu hier à chercher une salle libre ?","[Pause.]","Chaque semaine, une équipe de dix personnes perd quatre heures à cause de ça.","[Silence de 2 secondes.]","Nous avons créé Salle libre : une application qui affiche, en temps réel, quelles salles sont vides.","[Pause.]","Elle a été testée dans deux entreprises. Résultat : quatre-vingts pour cent de temps gagné.","[Regardez les décideurs.]","Aujourd’hui, nous cherchons trois entreprises pour un essai gratuit de deux mois.","[Pause.]","Si vous voulez gagner quatre heures par semaine, parlons-en dès aujourd’hui.","[Souriez. Silence de 2 secondes.]","Merci."]},{"id":"d8","s":"tra","n":1,"t":"Je ne suis pas prêt","but":"Parler malgré le trac en le nommant, puis en le mettant au service du message.","appris":[["L34","Gérer le trac"],["L35","Construire sa confiance"],["L36","L’intention et l’alignement"]],"controle":["J’ai respiré avant la première phrase.","Mon trac n’a pas accéléré ma voix.","J’ai fini en regardant quelqu’un, pas le sol."],"l":["[Posez vos pieds au sol. Respirez profondément.]","Bonjour.","[Pause.]","Je vais être honnête avec vous : mon cœur bat très vite.","[Souriez. Silence de 2 secondes.]","Et c’est normal.","[Pause.]","Mon corps croit que je vais affronter un danger.","[Pause.]","En réalité, il se prépare à bien faire.","[Ralentissez.]","Alors je ne vais pas lutter contre mon trac.","Je vais lui donner un travail : porter ma voix jusqu’au fond de la salle.","[Pause.]","Je n’ai pas besoin d’être parfait.","[Regardez quelqu’un au fond.]","J’ai besoin d’être là, présent, et sincère.","[Silence de 2 secondes.]","Voilà. J’ai commencé.","[Respirez. Silence final de 3 secondes.]"]},{"id":"h3","s":"hom","n":2,"t":"Mon grand-père et la mer","but":"Raconter un souvenir précis pour faire naître l’émotion, sans la commenter.","appris":[["L14","Raconter des histoires"],["L19","Intonation et émotion"],["L18","Débit et pauses"]],"controle":["J’ai décrit l’image avant d’en parler.","J’ai ralenti sur la phrase du filet.","Je n’ai pas expliqué mon émotion."],"l":["[Regardez un point au loin. Respirez.]","Mon grand-père sentait le sel et le tabac.","[Pause.]","Chaque dimanche, avant l’aube, il réparait son filet sur le seuil.","Je m’asseyais près de lui. Il ne parlait pas.","[Ralentissez.]","Il tendait simplement une extrémité du filet, et je tenais.","[Pause.]","Je tenais, sans savoir ce que je tenais.","[Silence de 2 secondes.]","Aujourd’hui, je sais.","Je tenais le fil entre lui et moi.","[Voix plus basse.]","Il est parti. Le filet est resté.","[Pause longue.]","Et chaque dimanche, avant l’aube, je tiens encore.","[Baissez le regard. Silence final de 3 secondes.]"]},{"id":"h4","s":"hom","n":1,"t":"Pour une amie d’enfance","but":"Dire l’amitié par des détails vrais et une phrase finale simple.","appris":[["L14","Raconter des histoires"],["L15","Citations et formules mémorables"],["L18","Débit et pauses"]],"controle":["J’ai donné au moins deux détails précis.","J’ai marqué le silence avant la dernière phrase.","J’ai souri en parlant des souvenirs joyeux."],"l":["[Souriez. Regardez-la.]","Léa, on se connaît depuis nos huit ans.","[Pause.]","Tu te souviens du vélo rouge que nous avons partagé pendant un été entier ?","Tu pédalais. Je criais. Nous tombions toujours au même virage.","[Pause.]","Les années ont passé. Les virages aussi.","[Ralentissez.]","Mais à chaque chute, tu étais là.","Pas pour dire « je t’avais prévenu ». Pour tendre la main.","[Silence de 2 secondes.]","On dit que les vrais amis se comptent sur les doigts d’une main.","[Pause.]","Moi, je n’ai besoin que d’un doigt, et il porte ton prénom.","[Souriez. Silence de 2 secondes.]","Merci d’être mon virage préféré.","[Silence final de 2 secondes.]"]},{"id":"h5","s":"hom","n":2,"t":"Pour un entraîneur","but":"Rendre hommage à un mentor en valorisant ce qu’il a transmis plus que ce qu’il a gagné.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L37","L’humilité et l’écoute"],["L19","Intonation et émotion"]],"controle":["J’ai parlé de ce qu’il a transmis, pas de ses trophées.","J’ai baissé la voix sur « Il nous a appris ».","J’ai regardé le coach sur la dernière phrase."],"l":["[Debout. Regardez le coach.]","Coach, vous nous avez donné des maillots.","[Pause.]","Mais ce n’est pas ce dont on se souviendra.","[Ralentissez.]","On se souviendra de vos mots, un mardi pluvieux, quand nous avions perdu :","« Perdre, ça fait mal. Mais ça ne vous apprend que si vous restez. »","[Silence de 2 secondes.]","Vous ne nous avez pas appris à gagner.","[Pause.]","Vous nous avez appris à rester.","[Voix posée.]","Rester quand c’est dur. Rester quand le score est mauvais. Rester les uns pour les autres.","[Pause longue.]","Alors aujourd’hui, c’est nous qui restons, un instant, pour vous dire merci.","[Regardez le coach. Silence final de 3 secondes.]"]},{"id":"h6","s":"hom","n":3,"t":"Fermer la maison familiale","but":"Dire un adieu à un lieu en faisant parler les objets, avec un rythme lent et une conclusion tournée vers l’avenir.","appris":[["L14","Raconter des histoires"],["L13","Le rythme et la musicalité"],["L9","La conclusion inoubliable"]],"controle":["J’ai nommé trois objets précis.","J’ai gardé un rythme lent du début à la fin.","J’ai fini sur l’avenir, pas sur la tristesse."],"l":["[Respirez. Regardez autour de vous.]","Cette porte grince depuis quarante ans.","[Pause.]","Cette table a vu mille repas, cent disputes, et une seule vraie réconciliation.","[Pause.]","Ce couloir garde encore la hauteur de chacun de nous, tracée au crayon.","[Silence de 2 secondes.]","On croit qu’une maison, c’est des murs.","[Ralentissez.]","Ce sont des voix. Des pas. Des odeurs de cuisine le dimanche.","[Pause.]","Et ces voix, nous les emportons.","[Voix plus chaude.]","Dans d’autres cuisines, d’autres couloirs, d’autres tables, nous ferons revivre ce qui s’est dit ici.","[Pause.]","Alors, ce soir, ne fermons pas une maison.","[Silence de 2 secondes.]","Ouvrons-en mille autres.","[Silence final de 3 secondes.]"]},{"id":"m3","s":"mot","n":1,"t":"Lundi, on recommence","but":"Relancer une équipe fatiguée avec des phrases courtes et une conclusion qui appelle à agir.","appris":[["L13","Le rythme et la musicalité"],["L38","Construire sa routine"],["L9","La conclusion inoubliable"]],"controle":["Mes phrases étaient courtes.","J’ai marqué un silence après « Lundi. »","J’ai fini sur une action simple."],"l":["[Souriez. Regardez l’équipe.]","Le projet a pris du retard. Je le sais. Vous le savez.","[Pause.]","Mais regardez ce que nous avons déjà fait.","Trois étapes terminées. Deux clients convaincus. Une équipe qui n’a pas lâché.","[Pause.]","Un retard, ce n’est pas un échec.","[Silence de 2 secondes.]","C’est une marche qu’on n’a pas encore montée.","[Montez la voix.]","Alors voici le plan : on souffle ce week-end.","Et lundi, on recommence.","[Pause.]","Pas parfaitement. Pas en courant. Pas à pas.","[Pleine voix.]","Lundi, on recommence. Ensemble.","[Silence de 2 secondes.]"]},{"id":"m4","s":"mot","n":2,"t":"Le dernier kilomètre","but":"Donner de l’énergie dans l’effort final avec une métaphore filée et une voix qui monte.","appris":[["L12","Les figures de style essentielles"],["L17","Volume et projection"],["L13","Le rythme et la musicalité"]],"controle":["J’ai filé la métaphore de la course.","Mon volume a monté à chaque palier.","J’ai terminé par un mot court et fort."],"l":["[Posture ancrée. Voix posée.]","Vous voyez la ligne d’arrivée ?","[Pause.]","Non ? Moi non plus.","[Pause.]","Et pourtant, elle est là.","[Silence de 2 secondes.]","Parce que le dernier kilomètre n’a pas de ligne visible.","Il a des jambes lourdes. Un souffle court. Une petite voix qui dit : « Arrête. »","[Montez la voix.]","Cette voix, on ne la fait pas taire.","On l’écoute. Puis on avance quand même.","[Pause.]","Un pas. Un autre. Un autre.","[Plus fort.]","Chaque pas qui vous fait mal est un pas que les autres n’ont pas fait.","[Pleine voix.]","Alors courez. Courez !","[Silence de 2 secondes.]","Courez, maintenant !"]},{"id":"m5","s":"mot","n":2,"t":"Nous ne sommes pas seuls","but":"Souder un groupe en alternant ethos (qui nous sommes), pathos (ce que nous ressentons) et logos (ce que nous avons prouvé).","appris":[["L2","Ethos, Pathos, Logos, Kairos"],["L5","Le plan classique en cinq temps"],["L9","La conclusion inoubliable"]],"controle":["J’ai dit « nous » plus souvent que « je ».","J’ai donné un chiffre avant l’émotion.","J’ai conclu avec une phrase qu’on peut répéter."],"l":["[Regardez le groupe. Voix posée.]","Il y a un an, nous étions douze.","[Pause.]","Aujourd’hui, nous sommes cent quarante.","[Silence de 2 secondes.]","Cent quarante personnes qui, chaque samedi, se lèvent pour les autres.","[Pause.]","Je me souviens du premier samedi.","Il pleuvait. Nous étions presque seuls. J’ai failli rentrer.","[Ralentissez.]","Mais quelqu’un est arrivé, puis un autre, puis un autre.","[Pause.]","On croit que seul, on est faible. On a raison.","[Montez la voix.]","Mais nous ne sommes pas seuls.","[Pleine voix.]","Seul, on commence. Ensemble, on change.","[Silence final de 3 secondes.]"]},{"id":"m6","s":"mot","n":3,"t":"Fier de ce que nous avons fait","but":"Célébrer un succès collectif en remerciant sans flatter, et ouvrir sur la suite.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L19","Intonation et émotion"],["L9","La conclusion inoubliable"]],"controle":["J’ai nommé un résultat précis.","J’ai remercié l’équipe, pas moi.","J’ai ouvert vers la suite en dernière phrase."],"l":["[Souriez. Prenez votre temps.]","Mesdames, Messieurs, chers amis,","[Pause.]","Il y a six mois, on nous disait que c’était impossible.","[Pause.]","Aujourd’hui, mille deux cents élèves savent mieux parler en public.","[Silence de 2 secondes.]","Ce chiffre ne porte pas mon nom.","[Ralentissez.]","Il porte celui de chaque formatrice, chaque bénévole, chaque élève qui est resté après l’heure.","[Regardez la salle.]","Je suis fier. Pas de moi. De nous.","[Pause.]","Mais un succès, ça se garde en avançant.","[Voix plus ferme.]","Alors, ce soir, on applaudit. Et demain, on recommence mieux.","[Souriez. Silence de 2 secondes.]"]},{"id":"c2","s":"con","n":1,"t":"Lire vingt minutes par jour","but":"Construire une idée simple : affirmation, raison, preuve, appel à agir.","appris":[["LX1","Construire une idée : affirmation, raison, preuve"],["L5","Le plan classique en cinq temps"],["L9","La conclusion inoubliable"]],"controle":["J’ai énoncé mon idée dès la première phrase.","J’ai donné une raison puis un exemple.","J’ai terminé par une action concrète."],"l":["[Regard fixe. Voix posée.]","Je vous propose une idée simple : lisez vingt minutes par jour.","[Pause.]","Pourquoi ? Parce que vingt minutes, c’est peu, mais chaque jour, ça change tout.","[Pause.]","Par exemple, à quinze pages par jour, on lit environ vingt livres par an.","Vingt livres. Sans y consacrer un seul week-end.","[Silence de 2 secondes.]","On me dira : « Je n’ai pas le temps. »","Mais vingt minutes, c’est le temps d’un trajet, d’une pause, d’un coucher.","[Pause.]","Alors ce soir, ouvrez un livre. Juste vingt minutes.","[Souriez. Silence de 2 secondes.]"]},{"id":"c3","s":"con","n":2,"t":"Dormir n’est pas perdre son temps","but":"Défendre une idée à contre-courant avec un plan en trois temps et des connecteurs nets.","appris":[["L5","Le plan classique en cinq temps"],["LX2","Les connecteurs : la colle du discours"],["LA2","Les types d’arguments et leur bon usage"]],"controle":["J’ai annoncé trois raisons avant de les dire.","J’ai utilisé « d’abord, ensuite, enfin ».","J’ai fini par une phrase à retenir."],"l":["[Posture droite. Regard fixe.]","On entend souvent : « Je dormirai quand j’aurai le temps. »","[Pause.]","Je veux vous montrer que c’est l’inverse. Dormir, c’est gagner du temps, pour trois raisons.","[Pause.]","D’abord, parce qu’on apprend en dormant : le cerveau trie et range ce qu’on a vu dans la journée.","Ensuite, parce qu’on décide mieux : quand on est fatigué, on se trompe plus et on s’énerve plus vite.","Enfin, parce qu’on a plus d’énergie : une heure bien dormie vaut souvent plus qu’une heure arrachée à la nuit.","[Silence de 2 secondes.]","Donc, ce soir, ne volez pas votre sommeil.","[Pause.]","Dormir, ce n’est pas perdre du temps.","[Ralentissez.]","C’est le placer à intérêts.","[Silence de 2 secondes.]"]},{"id":"c4","s":"con","n":2,"t":"Oser dire non","but":"Défendre une limite avec fermeté et respect, sans s’excuser à outrance.","appris":[["L41","Négocier, convaincre un individu"],["L33","Les situations difficiles"],["L37","L’humilité et l’écoute"]],"controle":["Mon « non » était dit sans excuse.","J’ai proposé une alternative.","Ma voix est restée posée."],"l":["[Posture stable. Voix basse et ferme.]","Dire non, ce n’est pas rejeter la personne.","[Pause.]","C’est protéger ce qui compte : son temps, son énergie, ses priorités.","[Pause.]","Quand on dit oui à tout, on finit par dire non à l’essentiel.","[Silence de 2 secondes.]","Alors voici une phrase à garder : « Merci d’y avoir pensé. Cette fois, ce n’est pas possible. »","[Pause.]","Pas de long discours. Pas de justification en dix points.","[Ralentissez.]","Si vous le pouvez, ajoutez une alternative : « En revanche, je peux vous aider jeudi. »","[Pause.]","Un non clair vaut mieux qu’un oui qui s’effondre.","[Regardez quelqu’un. Silence final de 2 secondes.]"]},{"id":"c5","s":"con","n":3,"t":"Apprendre une langue maintenant","but":"Trouver et classer des arguments avec les deux grilles, puis réfuter l’objection principale.","appris":[["LA1","Trouver des arguments : les deux grilles"],["LA4","Réfuter sans écraser"],["L45","L’art du débat"]],"controle":["J’ai annoncé deux avantages avant de les détailler.","J’ai reconnu l’objection avant d’y répondre.","J’ai conclu sur une date, pas sur un vœu."],"l":["[Souriez. Regard direct.]","Apprendre une langue, ce n’est pas un loisir. C’est un investissement.","[Pause.]","Pour deux raisons. Une raison personnelle : on pense autrement quand on parle autrement.","Et une raison pratique : une langue de plus, c’est plus de choix, plus de rencontres, plus d’offres de travail.","[Silence de 2 secondes.]","On me répond : « C’est trop long. »","[Hochez la tête.]","Vous avez raison, si l’on veut devenir parfait.","Mais pour se faire comprendre, vingt minutes par jour pendant six mois suffisent pour commencer.","[Pause.]","Alors ne demandez pas : « Quand serai-je prêt ? »","[Ralentissez.]","Choisissez une date. Lundi prochain. Et commencez.","[Silence de 2 secondes.]"]},{"id":"c6","s":"con","n":3,"t":"Participer, même quand c’est pénible","but":"Mobiliser des membres passifs : problème, raison de s’engager, action précise et petite.","appris":[["LA2","Les types d’arguments et leur bon usage"],["LX3","Annoncer et prévenir : le balisage et la prolepse"],["L9","La conclusion inoubliable"]],"controle":["J’ai annoncé mon plan avant de le dérouler.","J’ai demandé une action petite et précise.","J’ai reconnu l’effort avant de demander plus."],"l":["[Regardez la salle. Voix posée.]","Je vais vous parler de quelque chose d’ennuyeux : les réunions.","[Pause.]","Je vais vous dire pourquoi elles comptent, puis comment les rendre utiles.","[Pause.]","Pourquoi elles comptent ? Parce que ceux qui sont absents ne décident pas, et ceux qui se taisent non plus.","[Silence de 2 secondes.]","Comment les rendre utiles ? Un seul geste suffit : arriver avec une idée et la dire.","[Pause.]","Je sais que vous êtes fatigués. Je sais que vous donnez déjà beaucoup.","[Ralentissez.]","Je ne demande pas plus de temps. Je demande une phrase.","[Pause.]","Une phrase, une fois par mois, c’est la seule voix qu’on n’entendra pas si vous ne la prononcez pas.","[Silence final de 2 secondes.]"]},{"id":"e1","s":"exp","n":1,"t":"Le cycle de l’eau","but":"Expliquer un phénomène en trois étapes claires, avec une image pour aider à retenir.","appris":[["L7","Les méthodes rapides de création"],["L11","Le vocabulaire de l’orateur"],["LX4","Concéder, illustrer, reformuler"]],"controle":["J’ai annoncé les trois étapes avant de les expliquer.","J’ai utilisé une image (le voyage).","J’ai résumé en une phrase à la fin."],"l":["[Souriez. Voix claire.]","Imaginez une goutte d’eau qui fait le tour du monde sans jamais acheter de billet.","[Pause.]","Son voyage a trois étapes.","Première étape : le soleil chauffe la mer, et l’eau monte dans l’air sous forme de vapeur.","Deuxième étape : en altitude, la vapeur refroidit et forme des nuages.","Troisième étape : les gouttes deviennent trop lourdes et retombent en pluie.","[Pause.]","Cette pluie nourrit les rivières, qui retournent à la mer.","[Silence de 2 secondes.]","Et le voyage recommence.","[Pause.]","En une phrase : l’eau monte, se refroidit, retombe, et recommence.","[Silence de 2 secondes.]"]},{"id":"e2","s":"exp","n":1,"t":"Pourquoi y a-t-il des saisons ?","but":"Corriger une idée reçue avec un exemple simple, puis expliquer la vraie cause.","appris":[["L7","Les méthodes rapides de création"],["LX4","Concéder, illustrer, reformuler"],["L11","Le vocabulaire de l’orateur"]],"controle":["J’ai d’abord énoncé l’idée fausse.","J’ai donné la vraie cause en une phrase.","J’ai fait un geste pour montrer l’inclinaison."],"l":["[Regardez la salle. Voix claire.]","On croit souvent que l’été arrive quand la Terre se rapproche du soleil.","[Pause.]","C’est faux.","[Silence de 2 secondes.]","La vraie raison, c’est l’inclinaison. La Terre est penchée.","[Inclinez la main pour montrer.]","Quand l’hémisphère nord penche vers le soleil, il reçoit plus de lumière : c’est l’été.","Six mois plus tard, c’est l’hémisphère sud qui penche vers le soleil.","[Pause.]","Résultat : quand c’est l’été à Paris, c’est l’hiver à Antananarivo.","[Pause.]","Les saisons ne viennent pas de la distance.","[Ralentissez.]","Elles viennent de l’inclinaison.","[Silence de 2 secondes.]"]},{"id":"e3","s":"exp","n":2,"t":"Qu’est-ce qu’un budget ?","but":"Expliquer un concept abstrait avec un exemple chiffré et une règle simple.","appris":[["L7","Les méthodes rapides de création"],["LX4","Concéder, illustrer, reformuler"],["L11","Le vocabulaire de l’orateur"]],"controle":["J’ai donné un exemple chiffré avant la règle.","J’ai défini le mot avant de l’utiliser.","J’ai terminé par une règle à retenir."],"l":["[Voix claire. Rythme posé.]","Un budget, ce n’est pas une prison. C’est une carte.","[Pause.]","Voici l’idée : vous notez ce qui entre, et ce qui sort.","[Pause.]","Par exemple, vous gagnez mille euros. Vous payez quatre cents euros de loyer, trois cents euros de nourriture, cent euros de transport.","[Pause.]","Il vous reste deux cents euros. Cet argent n’est pas de l’argent libre : c’est de l’argent à décider.","[Silence de 2 secondes.]","Une règle simple : placez d’abord une petite somme de côté, puis dépensez ce qui reste.","[Pause.]","Un budget ne vous dit pas ce que vous n’avez pas le droit de faire.","[Ralentissez.]","Il vous dit où va votre argent avant que vous vous demandiez où il est passé.","[Silence de 2 secondes.]"]},{"id":"e4","s":"exp","n":2,"t":"Comment fonctionne Internet","but":"Expliquer une technique complexe avec une analogie et trois étapes.","appris":[["LX4","Concéder, illustrer, reformuler"],["L7","Les méthodes rapides de création"],["L12","Les figures de style essentielles"]],"controle":["J’ai filé l’analogie de la poste.","J’ai gardé des phrases courtes.","J’ai résumé en une phrase."],"l":["[Souriez. Voix claire.]","Internet, c’est d’abord un énorme service postal.","[Pause.]","Quand vous envoyez un message, il est découpé en petits paquets, comme des lettres.","Chaque paquet reçoit une adresse.","[Pause.]","Ensuite, les paquets voyagent par des routes différentes : câbles, antennes, satellites.","[Pause.]","Enfin, à l’arrivée, ils sont remis dans le bon ordre, et le message se reforme.","[Silence de 2 secondes.]","Tout cela se passe en une fraction de seconde.","[Pause.]","En une phrase : un message est découpé, envoyé par différents chemins, puis reconstitué à l’arrivée.","[Silence de 2 secondes.]"]},{"id":"e5","s":"exp","n":1,"t":"La photosynthèse en une minute","but":"Expliquer un processus scientifique à un public sans connaissance, avec une recette comme image.","appris":[["L7","Les méthodes rapides de création"],["LX4","Concéder, illustrer, reformuler"],["L11","Le vocabulaire de l’orateur"]],"controle":["J’ai utilisé la recette de cuisine comme image.","J’ai nommé les trois ingrédients.","J’ai fini par ce que la plante produit."],"l":["[Souriez. Rythme posé.]","Une plante fait sa propre cuisine.","[Pause.]","Sa recette a trois ingrédients : de la lumière, de l’eau, et du gaz carbonique, qu’elle prend dans l’air.","[Pause.]","Avec cela, elle fabrique son aliment : du sucre.","[Pause.]","Et dans cette cuisine, il y a un déchet : de l’oxygène. Celui que nous respirons.","[Silence de 2 secondes.]","Autrement dit, chaque feuille nourrit la plante, et en plus, elle nous fait respirer.","[Pause.]","Une plante qui fait son repas, c’est aussi un coup de pouce pour l’air.","[Silence de 2 secondes.]"]},{"id":"e6","s":"exp","n":2,"t":"Qu’est-ce que l’inflation ?","but":"Expliquer une notion économique avec un panier de courses et une conséquence concrète.","appris":[["LX4","Concéder, illustrer, reformuler"],["L11","Le vocabulaire de l’orateur"],["L7","Les méthodes rapides de création"]],"controle":["J’ai expliqué avec un panier de courses.","J’ai donné une conséquence concrète.","J’ai évité le jargon."],"l":["[Voix claire. Posture simple.]","Imaginez un panier de courses qui coûtait cent euros l’an dernier.","[Pause.]","Cette année, le même panier coûte cent cinq euros.","[Pause.]","Vous n’avez pas acheté plus. Les prix ont simplement monté de cinq pour cent.","[Silence de 2 secondes.]","Voilà l’inflation : la hausse générale des prix.","[Pause.]","La conséquence ? Avec le même salaire, on achète un peu moins de choses.","[Pause.]","Voilà pourquoi, quand les prix montent, les salaires doivent suivre, sinon le pouvoir d’achat baisse.","[Ralentissez.]","L’inflation, c’est quand votre argent perd un peu de sa force.","[Silence de 2 secondes.]"]},{"id":"e7","s":"exp","n":2,"t":"Pourquoi on dort : les cycles du sommeil","but":"Expliquer un fonctionnement du corps avec une structure simple et un conseil à la fin.","appris":[["L7","Les méthodes rapides de création"],["LX4","Concéder, illustrer, reformuler"],["L5","Le plan classique en cinq temps"]],"controle":["J’ai annoncé les deux phases.","J’ai donné un conseil concret à la fin.","J’ai gardé une voix calme."],"l":["[Voix calme. Ralentissez.]","Dormir, ce n’est pas s’éteindre.","[Pause.]","Pendant la nuit, le cerveau enchaîne des cycles d’environ une heure et demie.","[Pause.]","Dans chaque cycle, il y a deux grandes phases : le sommeil profond, où le corps récupère, et le sommeil paradoxal, où l’on rêve et où le cerveau trie les souvenirs.","[Silence de 2 secondes.]","Une nuit complète, c’est quatre à six de ces cycles.","[Pause.]","Conseil : si vous devez vous réveiller, mieux vaut le faire à la fin d’un cycle.","[Pause.]","Régularité, voilà le mot : couchez-vous à heure fixe, et votre corps fera le reste.","[Silence de 2 secondes.]"]},{"id":"e8","s":"exp","n":3,"t":"Comment lire une carte","but":"Donner un mode d’emploi oral en étapes ordonnées, avec des gestes pour guider l’écoute.","appris":[["L7","Les méthodes rapides de création"],["L5","Le plan classique en cinq temps"],["L24","Les gestes"]],"controle":["J’ai annoncé « trois repères ».","J’ai accompagné chaque repère d’un geste.","J’ai résumé à la fin."],"l":["[Debout. Mains devant vous.]","Lire une carte, c’est trouver trois repères.","[Pause.]","Premier repère : la légende. Elle dit ce que signifient les couleurs et les symboles.","[Montrez un coin.]","Deuxième repère : l’échelle. Elle dit combien de kilomètres représente un centimètre.","[Mesurez avec les doigts.]","Troisième repère : le nord. Il donne l’orientation.","[Pointez vers le haut.]","[Pause.]","Avec ces trois repères, vous savez où vous êtes, où vous allez, et à quelle distance.","[Silence de 2 secondes.]","Légende, échelle, nord : trois mots, et une carte n’a plus de secret.","[Silence de 2 secondes.]"]},{"id":"r2","s":"rem","n":1,"t":"Remercier un jury","but":"Remercier avec sobriété et retenir une idée du jury, pour montrer qu’on a écouté.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L37","L’humilité et l’écoute"],["L31","Lire les réactions en direct"]],"controle":["J’ai remercié en regardant le jury.","J’ai repris une remarque précise du jury.","J’ai terminé court."],"l":["[Souriez. Regardez le jury.]","Mesdames, Messieurs les membres du jury,","[Pause.]","Je vous remercie du temps que vous m’avez consacré.","[Pause.]","Madame Durand, votre question sur le financement m’a obligé à voir ce que j’avais négligé.","[Pause.]","Monsieur Perrin, votre conseil de simplifier mon plan est celui que j’appliquerai dès demain.","[Silence de 2 secondes.]","On présente son travail pour être jugé. On en sort plus lucide.","[Pause.]","Pour cela, merci.","[Inclinez légèrement la tête. Silence de 2 secondes.]"]},{"id":"r3","s":"rem","n":2,"t":"Merci à mon équipe de bénévoles","but":"Remercier un groupe en donnant à chacun un rôle précis et en finissant sur l’impact collectif.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L23","Le regard"],["L15","Citations et formules mémorables"]],"controle":["J’ai cité au moins trois rôles différents.","J’ai regardé les personnes en les nommant.","J’ai fini par un résultat chiffré."],"l":["[Souriez. Prenez votre temps.]","Ce week-end, trois cents personnes sont venues. Et pas une n’a attendu plus de dix minutes.","[Pause.]","Ce n’est pas un hasard.","[Pause.]","C’est Nadia, à l’accueil, qui a souri à chaque visage.","C’est Karim, au fond, qui a monté les chaises avant le lever du jour.","C’est Hanta, derrière la caisse, qui n’a jamais fait une erreur de monnaie.","[Silence de 2 secondes.]","Un événement réussi, on le voit.","[Ralentissez.]","Mais ce qui le fait réussir, on ne le voit presque jamais.","[Pause.]","Alors ce soir, je le dis : merci.","[Regardez-les. Silence de 3 secondes.]"]},{"id":"r4","s":"rem","n":2,"t":"Féliciter un lauréat","but":"Féliciter en racontant le chemin parcouru, et passer la parole au lauréat avec élégance.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L14","Raconter des histoires"],["L9","La conclusion inoubliable"]],"controle":["J’ai raconté un moment précis du parcours.","J’ai félicité sans exagérer.","J’ai passé la parole clairement."],"l":["[Souriez. Regardez le lauréat.]","Il y a deux ans, Alex arrivait ici sans oser parler en groupe.","[Pause.]","Aujourd’hui, il vient de convaincre un jury de cent personnes.","[Pause.]","Je me souviens d’un jeudi où il a recommencé son discours douze fois.","Douze. Sans râler. Il disait : « Encore une fois, et ce sera mieux. »","[Silence de 2 secondes.]","Et c’était mieux, à chaque fois.","[Pause.]","Alex, ce prix récompense un résultat.","[Ralentissez.]","Mais surtout, il récompense ta façon de recommencer.","[Pause.]","Félicitations. La scène est à toi.","[Tendez la main. Silence de 2 secondes.]"]},{"id":"p2","s":"pro","n":1,"t":"Me présenter en trente secondes","but":"Se présenter avec une structure simple : qui je suis, ce que je fais, ce que je cherche.","appris":[["LB1","Réunion, entretien, pitch"],["L8","L’introduction parfaite"],["L47","Répondre aux questions : PREP et STAR"]],"controle":["J’ai respecté la structure en trois parties.","J’ai tenu trente secondes environ.","J’ai souri en commençant."],"l":["[Debout. Souriez.]","Bonjour, je m’appelle Maya.","[Pause.]","Je suis étudiante en marketing, et j’aide des petites associations à mieux se faire connaître.","[Pause.]","Mon dernier projet : doubler les inscriptions d’un club de théâtre en trois mois.","[Silence de 2 secondes.]","Aujourd’hui, je cherche un stage dans la communication d’une entreprise engagée.","[Pause.]","Si vous voulez voir ce que je sais faire, je serai ravie d’en parler.","[Souriez. Silence de 2 secondes.]","Merci."]},{"id":"p3","s":"pro","n":2,"t":"Ouvrir une réunion","but":"Ouvrir une réunion avec objectif, durée et décision attendue, pour que chacun sache pourquoi il est là.","appris":[["LB1","Réunion, entretien, pitch"],["L8","L’introduction parfaite"],["L5","Le plan classique en cinq temps"]],"controle":["J’ai annoncé l’objectif, la durée et la décision attendue.","J’ai regardé les participants.","J’ai terminé par la première question."],"l":["[Debout. Voix posée.]","Bonjour à tous, merci d’être là.","[Pause.]","Nous avons vingt minutes, un seul objectif, et une seule décision à prendre.","[Pause.]","L’objectif : choisir la date du lancement.","[Pause.]","La décision : jeudi ou vendredi.","[Pause.]","Je vous propose trois tours : d’abord les contraintes, ensuite les risques, enfin le vote.","[Silence de 2 secondes.]","Si une idée sort de ce cadre, je la note et nous y reviendrons à la fin.","[Pause.]","Première question : qui voit un obstacle pour jeudi ?","[Regardez la salle. Silence de 3 secondes.]"]},{"id":"p4","s":"pro","n":3,"t":"Défendre mon budget","but":"Défendre une demande chiffrée : situation, problème, solution, demande, en utilisant PREP.","appris":[["L47","Répondre aux questions : PREP et STAR"],["LB1","Réunion, entretien, pitch"],["L5","Le plan classique en cinq temps"]],"controle":["J’ai suivi PREP : point, raison, exemple, point.","J’ai donné un chiffre clair.","J’ai terminé par la demande."],"l":["[Posture droite. Regard direct.]","Je demande dix mille euros pour la formation de l’équipe.","[Pause.]","Pourquoi ? Parce que chaque erreur de saisie nous coûte du temps, et nous en faisons une par jour.","[Pause.]","Par exemple, le mois dernier, vingt erreurs nous ont fait perdre quarante heures de travail.","[Silence de 2 secondes.]","Dix mille euros de formation, c’est environ le prix de ces heures perdues sur un an.","[Pause.]","Donc je vous demande aujourd’hui dix mille euros pour que cela ne se reproduise plus.","[Silence de 2 secondes.]","Merci. Je réponds volontiers à vos questions."]},{"id":"p5","s":"pro","n":3,"t":"Parlez-moi de vous","but":"Répondre à la question d’entretien la plus classique avec la méthode STAR : situation, tâche, action, résultat.","appris":[["L47","Répondre aux questions : PREP et STAR"],["LB1","Réunion, entretien, pitch"],["L36","L’intention et l’alignement"]],"controle":["J’ai raconté une seule histoire, pas ma vie.","J’ai donné un résultat chiffré.","J’ai fini en reliant à l’entreprise."],"l":["[Souriez. Regard direct.]","Je vais vous raconter un moment qui me définit.","[Pause.]","L’an dernier, notre association manquait de bénévoles. Nous en avions dix, il en fallait trente.","[Pause.]","J’ai proposé d’aller dans les lycées présenter l’action en cinq minutes.","[Pause.]","En deux mois, nous avons accueilli vingt-sept nouvelles personnes.","[Silence de 2 secondes.]","Ce que j’en retiens : je passe à l’action quand il manque quelque chose.","[Pause.]","Et c’est ce que j’aimerais apporter à votre équipe.","[Silence de 2 secondes.]"]},{"id":"t2","s":"tra","n":1,"t":"Mon premier jour de prise de parole","but":"Dédramatiser un début en acceptant l’imperfection, avec un ton honnête et simple.","appris":[["L34","Gérer le trac"],["L35","Construire sa confiance"],["L36","L’intention et l’alignement"]],"controle":["J’ai respiré avant de commencer.","J’ai parlé lentement malgré le trac.","J’ai fini par une phrase d’encouragement."],"l":["[Respirez. Posez vos pieds au sol.]","Je suis là. C’est déjà beaucoup.","[Pause.]","Il y a un an, je n’aurais pas osé lever la main.","Aujourd’hui, je suis debout devant vous.","[Silence de 2 secondes.]","Ma voix tremble un peu. Mes mains aussi.","[Pause.]","Et alors ?","[Souriez.]","Personne ici n’attend de moi la perfection.","Ils attendent quelqu’un qui ose.","[Pause.]","Alors je dis ma première phrase.","[Silence de 2 secondes.]","Voilà. Elle est dite.","La suivante sera plus facile.","[Respirez. Silence final de 2 secondes.]"]},{"id":"t3","s":"tra","n":2,"t":"Quand je perds le fil","but":"S’entraîner à rebondir après un trou de mémoire : respirer, relire un mot clé, reprendre sans s’excuser.","appris":[["L28","Parler sans notes"],["L33","Les situations difficiles"],["L34","Gérer le trac"]],"controle":["J’ai respiré pendant le trou.","Je n’ai pas dit « excusez-moi ».","J’ai repris avec un mot clé."],"l":["[Debout. Parlez normalement.]","Je vais vous parler de la lumière…","[Silence de 4 secondes. Respirez. Ne vous excusez pas.]","La lumière, c’est ce qui nous permet de voir.","[Pause.]","Voilà. Vous venez de voir ce qu’est un trou de mémoire, et ce qu’il vaut.","[Pause.]","Presque rien.","[Souriez.]","Le public n’entend pas votre silence comme vous l’entendez.","Il entend quelqu’un qui réfléchit.","[Pause.]","Respirez. Cherchez un mot clé. Reprenez.","[Silence de 2 secondes.]","Un trou de mémoire, c’est une pause qu’on a oublié de décorer.","[Silence de 2 secondes.]"]},{"id":"t4","s":"tra","n":2,"t":"Je vais me tromper, et alors ?","but":"Construire sa confiance en acceptant l’erreur comme une étape normale du progrès.","appris":[["L35","Construire sa confiance"],["L38","Construire sa routine"],["L36","L’intention et l’alignement"]],"controle":["J’ai dit « me tromper » sans baisser la voix.","J’ai souri sur « et alors ».","J’ai terminé avec confiance."],"l":["[Debout. Regard droit.]","Je vais me tromper.","[Pause.]","Pas une fois. Plusieurs fois.","[Pause.]","Et alors ?","[Silence de 2 secondes.]","Un orateur ne se mesure pas au nombre d’erreurs qu’il évite.","Il se mesure au nombre de fois où il continue.","[Pause.]","Chaque erreur est une information.","[Ralentissez.]","Elle dit : « Ici, travaille. »","[Pause.]","Alors je ne vais pas éviter l’erreur.","[Pleine voix.]","Je vais la traverser.","[Silence de 2 secondes.]"]},{"id":"v1","s":"voi","n":1,"t":"Le discours du souffle","but":"Travailler le souffle : parler sur une seule expiration et placer ses respirations aux bons endroits.","appris":[["L21","L’échauffement vocal"],["L16","Comprendre sa voix"],["L18","Débit et pauses"]],"controle":["J’ai respiré aux virgules, pas au milieu des mots.","Mon ventre se gonflait à l’inspiration.","Ma voix est restée stable jusqu’au bout."],"l":["[Debout. Mains sur le ventre. Inspirez par le nez.]","Je respire.","[Respirez. Silence de 3 secondes.]","J’inspire avant de parler, et je parle en soufflant.","[Respirez. Pause.]","Chaque phrase est portée par l’air que je viens de prendre.","[Respirez. Pause.]","Quand ma phrase est trop longue, je n’attends pas d’être à bout de souffle.","[Pause.]","Je place une pause. Je respire. Je continue.","[Silence de 2 secondes.]","Un souffle bien placé vaut mieux qu’une phrase poussée jusqu’au bout.","[Respirez. Silence final de 3 secondes.]"]},{"id":"v2","s":"voi","n":2,"t":"Du chuchotement au grand cri","but":"Travailler la gamme du volume : chuchoter, parler, projeter, sans forcer la gorge.","appris":[["L17","Volume et projection"],["L19","Intonation et émotion"],["L21","L’échauffement vocal"]],"controle":["J’ai montré trois niveaux de volume nets.","Je n’ai pas forcé la gorge.","J’ai terminé en pleine voix projetée."],"l":["[Debout. Respirez. Voix très basse.]","Je chuchote. Vous m’entendez à peine.","[Pause.]","[Voix normale.]","Je parle. Vous m’entendez bien.","[Pause.]","[Voix projetée, comme pour le fond de la salle.]","Je projette. Vous m’entendez tous.","[Pause.]","[Retour à la voix posée.]","Voyez-vous, ce n’est pas crier. C’est envoyer sa voix plus loin, avec le ventre.","[Silence de 2 secondes.]","Et le plus fort, parfois, c’est de retourner au chuchotement.","[Voix très basse.]","Parce que tout le monde se penche.","[Silence de 3 secondes.]"]},{"id":"v3","s":"voi","n":1,"t":"Parler lentement","but":"S’entraîner à ralentir son débit et à marquer des pauses sans les combler.","appris":[["L18","Débit et pauses"],["L16","Comprendre sa voix"],["L34","Gérer le trac"]],"controle":["J’ai marqué chaque pause jusqu’au bout.","Mon débit était plus lent qu’en conversation.","Je n’ai pas dit « euh »."],"l":["[Respirez. Parlez deux fois plus lentement que d’habitude.]","Je parle.","[Pause.]","Lentement.","[Pause.]","Chaque mot","[Pause.]","a son temps.","[Silence de 2 secondes.]","Quand je vais vite, vous retenez peu.","[Pause.]","Quand je ralentis, vous retenez tout.","[Silence de 2 secondes.]","Je n’ai pas besoin de remplir les silences.","[Pause.]","Ils travaillent pour moi.","[Silence final de 3 secondes.]"]},{"id":"v4","s":"voi","n":2,"t":"Le regard qui tient la salle","but":"S’entraîner à répartir son regard : une idée, une personne, puis une autre.","appris":[["L23","Le regard"],["L31","Lire les réactions en direct"],["L30","Connaître son auditoire"]],"controle":["J’ai regardé une personne par idée.","Je n’ai pas balayé la salle trop vite.","J’ai terminé en regardant le fond."],"l":["[Regardez la personne à votre gauche.]","Une idée. Une personne.","[Pause.]","[Regardez la personne à votre droite.]","Une autre idée. Une autre personne.","[Pause.]","[Regardez le milieu de la salle.]","Mon regard ne balaie pas. Il se pose.","[Pause.]","[Regardez le fond.]","Il va même jusqu’au fond, pour dire à chacun : je vous parle aussi.","[Silence de 2 secondes.]","Un regard tenu deux secondes dit : « Vous comptez. »","[Pause.]","Un regard qui fuit dit le contraire.","[Regardez quelqu’un. Silence final de 3 secondes.]"]},{"id":"v5","s":"voi","n":2,"t":"Les gestes qui parlent","but":"Utiliser des gestes simples et ouverts qui accompagnent le sens, sans s’agiter.","appris":[["L24","Les gestes"],["L22","La posture"],["L19","Intonation et émotion"]],"controle":["Mes gestes restaient dans la zone du buste.","Chaque geste illustrait un mot du texte.","Mes mains sont revenues au repos entre les gestes."],"l":["[Debout. Mains au repos.]","Quand je parle d’une grande idée, mes mains s’ouvrent.","[Ouvrez les mains.]","Quand je parle de trois points, mes doigts comptent.","[Comptez avec les doigts.]","Quand je parle de ce qui est petit, mes mains se rapprochent.","[Rapprochez les mains.]","Et quand je n’ai rien à montrer, mes mains reposent.","[Mains au repos.]","Pas de geste pour remplir. Pas de geste pour cacher le trac.","[Pause.]","Un geste utile se voit.","[Ralentissez.]","Un geste inutile se remarque.","[Silence de 2 secondes.]"]},{"id":"v6","s":"voi","n":1,"t":"Articuler","but":"Travailler la diction avec des phrases difficiles, à dire lentement puis plus vite.","appris":[["L20","Articulation et diction"],["L21","L’échauffement vocal"],["L18","Débit et pauses"]],"controle":["J’ai exagéré les consonnes la première fois.","J’ai accéléré sans perdre en netteté.","J’ai détendu ma mâchoire entre deux phrases."],"l":["[Détendez la mâchoire. Respirez.]","Premier essai, lentement.","[Pause.]","Six chasseurs chassent six chats sans sauter.","[Pause.]","Trois gros rats gris grattent trois gros rois gras.","[Pause.]","Deuxième essai, plus vite, mais net.","[Pause.]","Un chasseur sachant chasser sait chasser sans son chien.","[Silence de 2 secondes.]","L’important n’est pas la vitesse.","[Ralentissez.]","C’est que chaque consonne soit entendue.","[Silence de 2 secondes.]"]},{"id":"q1","s":"com","n":2,"t":"Répondre à une question piège","but":"Garder son calme face à une question piégeuse : reformuler, répondre sur le fond, revenir à son message.","appris":[["L32","Gérer questions et interruptions"],["L47","Répondre aux questions : PREP et STAR"],["L33","Les situations difficiles"]],"controle":["J’ai reformulé avant de répondre.","Mon ton est resté calme.","J’ai terminé sur mon message principal."],"l":["[Souriez. Prenez un temps.]","Si je comprends bien, vous demandez si ce projet n’est pas trop cher.","[Pause.]","C’est une vraie question, et elle mérite une vraie réponse.","[Pause.]","Le coût est de vingt mille euros. Mais il évite deux postes de dépenses qui, ensemble, dépassent trente mille.","[Silence de 2 secondes.]","Donc la bonne question est peut-être : combien coûte de ne rien faire ?","[Pause.]","Et pour cela, ce projet reste la solution la plus économique.","[Silence de 2 secondes.]","Merci pour cette question, elle nous fait avancer."]},{"id":"q2","s":"com","n":2,"t":"Recevoir une critique","but":"Accueillir une critique sans se défendre ni s’effondrer : écouter, remercier, ajuster.","appris":[["L37","L’humilité et l’écoute"],["LA4","Réfuter sans écraser"],["L32","Gérer questions et interruptions"]],"controle":["Je n’ai pas coupé la parole.","J’ai remercié avant de répondre.","J’ai proposé un ajustement concret."],"l":["[Écoutez. Hochez la tête. Silence de 3 secondes.]","Merci pour ce retour.","[Pause.]","Si je résume, vous dites que mon introduction est trop longue.","[Pause.]","Vous avez raison sur un point : elle dure quatre minutes, et l’idée principale n’arrive qu’à la troisième.","[Silence de 2 secondes.]","Je vais la raccourcir et placer l’idée dès la première phrase.","[Pause.]","Pourriez-vous me dire, après, si c’est plus clair ?","[Souriez. Silence de 2 secondes.]","Une critique bien reçue vaut un coach gratuit.","[Silence de 2 secondes.]"]},{"id":"q3","s":"com","n":3,"t":"Réfuter sans écraser","but":"Réfuter un argument avec respect : reconnaître le vrai, montrer la limite, proposer mieux.","appris":[["LA4","Réfuter sans écraser"],["LA3","Les sophismes à reconnaître (et à éviter)"],["L45","L’art du débat"]],"controle":["J’ai reconnu ce qui est vrai chez l’autre.","J’ai montré la limite en une phrase.","Je n’ai pas attaqué la personne."],"l":["[Voix posée. Regard ouvert.]","Mon contradicteur dit que le télétravail rend les équipes moins efficaces.","[Pause.]","Il a raison sur un point : sans règles, on se disperse.","[Pause.]","Mais l’argument s’arrête là.","[Pause.]","Car beaucoup d’équipes, avec des règles claires, constatent le contraire.","[Silence de 2 secondes.]","Alors posons-nous la bonne question, pas « télétravail ou bureau ? », mais « avec quelles règles ? »","[Pause.]","Sur ce point, je crois que nous pouvons être d’accord.","[Souriez. Silence de 2 secondes.]"]},{"id":"q4","s":"com","n":3,"t":"Face à un public hostile","but":"Garder la maîtrise quand l’ambiance se tend : ralentir, reconnaître le désaccord, revenir à un terrain commun.","appris":[["L33","Les situations difficiles"],["L31","Lire les réactions en direct"],["L34","Gérer le trac"]],"controle":["J’ai ralenti quand l’ambiance s’est tendue.","J’ai reconnu le désaccord sans me justifier.","J’ai terminé sur un terrain commun."],"l":["[Respirez. Gardez les épaules basses.]","Je vois que beaucoup d’entre vous ne sont pas d’accord.","[Pause.]","C’est normal. C’est même sain.","[Silence de 2 secondes.]","Je ne vais pas vous demander de changer d’avis maintenant.","[Pause.]","Je vous demande seulement de m’écouter jusqu’au bout.","[Pause.]","Après, vous déciderez.","[Ralentissez.]","Nous voulons tous la même chose : que ce quartier soit plus sûr.","[Pause.]","Nous ne sommes pas d’accord sur le chemin.","[Pause.]","Alors regardons-le ensemble.","[Silence de 2 secondes.]"]},{"id":"q5","s":"com","n":3,"t":"Conclure un débat","but":"Conclure un débat en résumant sa position en une phrase, en reconnaissant l’adversaire et en laissant une image.","appris":[["L45","L’art du débat"],["L9","La conclusion inoubliable"],["LX5","Assembler, écouter, vérifier"]],"controle":["J’ai résumé ma position en une phrase.","J’ai reconnu un point juste de l’adversaire.","J’ai fini sur une image."],"l":["[Regardez la salle. Voix posée.]","Résumons.","[Pause.]","Mon adversaire a raison sur un point : changer demande des efforts.","[Pause.]","Mais je vous ai montré trois choses : que le coût est faible, que le gain est réel, et que le risque est limité.","[Silence de 2 secondes.]","Alors la question n’est plus « pourquoi changer ? »","[Pause.]","C’est « pourquoi attendre ? »","[Ralentissez.]","Une porte entrouverte ne le restera pas longtemps.","[Pause.]","Poussons-la.","[Silence de 3 secondes.]"]},{"id":"s1","s":"spe","n":2,"t":"Toast de mariage","but":"Faire un toast chaleureux et bref : un souvenir, une qualité de chacun, un vœu.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L14","Raconter des histoires"],["L9","La conclusion inoubliable"]],"controle":["J’ai raconté un souvenir en moins de vingt secondes.","J’ai souri en parlant des mariés.","J’ai levé mon verre sur la dernière phrase."],"l":["[Souriez. Verre à la main.]","Chers amis, chère famille,","[Pause.]","Je connais Julie depuis dix ans, et Thomas depuis dix minutes.","[Rires. Pause.]","Mais il m’a suffi de dix minutes pour voir pourquoi elle l’a choisi.","[Pause.]","Julie est la personne qui rit de ses propres bêtises.","Thomas est celui qui les rattrape sans la gronder.","[Silence de 2 secondes.]","On dit que le mariage, c’est trouver quelqu’un avec qui on peut être soi-même, même quand on n’est pas au meilleur de soi.","[Pause.]","Vous, vous l’avez trouvé.","[Levez le verre.]","À Julie et à Thomas : que vos rires soient plus longs que vos disputes !","[Silence de 2 secondes.]"]},{"id":"s2","s":"spe","n":1,"t":"Discours d’anniversaire","but":"Souhaiter un anniversaire avec humour et sincérité, en finissant par un vœu.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L14","Raconter des histoires"],["L19","Intonation et émotion"]],"controle":["J’ai souri en commençant.","J’ai donné un détail drôle et un détail tendre.","J’ai terminé par un vœu clair."],"l":["[Souriez. Regardez la personne.]","Maman, tu as cinquante ans aujourd’hui.","[Pause.]","Et je me suis promis de ne pas en parler.","[Rires. Pause.]","Ce que je veux dire, c’est que tu as toujours su rire des choses difficiles.","Même quand tu as brûlé le gâteau d’anniversaire de mon frère, tu as dit : « Ce n’est pas du charbon, c’est une œuvre d’art. »","[Silence de 2 secondes.]","Mais je veux aussi te dire merci.","[Ralentissez.]","Merci d’avoir toujours cru en moi, même quand je n’y croyais pas.","[Pause.]","Je te souhaite une année pleine de rires, de voyages, et de gâteaux non brûlés.","[Levez le verre. Silence de 2 secondes.]"]},{"id":"s3","s":"spe","n":2,"t":"Inauguration","but":"Inaugurer un lieu : situer l’histoire, nommer ceux qui l’ont rendu possible, ouvrir vers l’usage.","appris":[["LB3","Présenter un orateur, remercier, féliciter"],["L9","La conclusion inoubliable"],["L8","L’introduction parfaite"]],"controle":["J’ai raconté l’histoire du lieu en une minute.","J’ai remercié trois contributeurs.","J’ai ouvert vers l’usage."],"l":["[Souriez. Regardez la salle.]","Mesdames, Messieurs,","[Pause.]","Il y a trois ans, ici, il y avait un terrain vague.","[Pause.]","Aujourd’hui, vous êtes dans une bibliothèque de quatre mille livres.","[Silence de 2 secondes.]","Ce miracle a des noms.","Merci à la mairie, qui a cru au projet. Merci aux artisans, qui ont travaillé dans le froid. Merci aux habitants, qui ont donné leurs livres.","[Pause.]","Une bibliothèque n’est pas faite de murs, mais de personnes qui lisent.","[Ralentissez.]","Alors je déclare cette bibliothèque ouverte.","[Pause.]","Entrez. Lisez. Revenez.","[Silence de 2 secondes.]"]},{"id":"s4","s":"spe","n":2,"t":"Remise de diplôme","but":"Marquer le passage d’une étape avec des mots simples, un conseil et un encouragement.","appris":[["L9","La conclusion inoubliable"],["L15","Citations et formules mémorables"],["LB3","Présenter un orateur, remercier, féliciter"]],"controle":["J’ai donné un seul conseil, pas dix.","J’ai fini par un encouragement.","J’ai souri aux diplômés."],"l":["[Souriez. Regardez les diplômés.]","Chers diplômés,","[Pause.]","Vous avez passé des nuits blanches, des examens, des doutes.","[Pause.]","Et vous êtes là.","[Silence de 2 secondes.]","Je ne vais pas vous donner dix conseils. Un seul.","[Pause.]","Restez curieux.","[Pause.]","Le diplôme ouvre une porte. Mais c’est la curiosité qui vous fait traverser les suivantes.","[Silence de 2 secondes.]","Vous ne savez pas tout. Personne ne sait tout.","[Ralentissez.]","Mais vous savez apprendre. C’est la seule compétence qui ne s’efface pas.","[Pause.]","Félicitations. Le monde vous attend.","[Silence de 2 secondes.]"]},{"id":"s5","s":"spe","n":1,"t":"Souhaiter la bonne année à l’équipe","but":"Souhaiter la nouvelle année en regardant en arrière, en remerciant, et en ouvrant sur un objectif commun.","appris":[["L9","La conclusion inoubliable"],["LB3","Présenter un orateur, remercier, féliciter"],["L13","Le rythme et la musicalité"]],"controle":["J’ai fait un bilan en trois mots.","J’ai remercié l’équipe.","J’ai terminé par un vœu partagé."],"l":["[Souriez. Regardez l’équipe.]","Une année s’achève. Trois mots pour la résumer : effort, progrès, fierté.","[Pause.]","Effort, parce que rien ne nous a été donné.","Progrès, parce que nous faisons mieux qu’il y a douze mois.","Fierté, parce que vous êtes là.","[Silence de 2 secondes.]","Merci pour votre travail. Merci pour votre confiance.","[Pause.]","L’année qui vient, je ne vous souhaite pas la facilité.","[Pause.]","Je vous souhaite d’oser, de réussir, et de le faire ensemble.","[Levez votre verre. Silence de 2 secondes.]","Bonne année à tous."]},{"id":"s6","s":"spe","n":1,"t":"Accueillir des invités","but":"Accueillir avec chaleur : saluer, expliquer le déroulé, mettre à l’aise.","appris":[["L8","L’introduction parfaite"],["L30","Connaître son auditoire"],["L35","Construire sa confiance"]],"controle":["J’ai souri en regardant l’assistance.","J’ai annoncé le déroulé.","J’ai terminé par une invitation chaleureuse."],"l":["[Souriez. Les bras ouverts.]","Bonsoir, et bienvenue !","[Pause.]","Je suis ravi de vous voir aussi nombreux ce soir.","[Pause.]","Voici le programme : d’abord un mot de présentation, ensuite une courte projection, enfin un buffet.","[Pause.]","Il n’y a aucune obligation. Posez vos questions, circulez, rencontrez-vous.","[Silence de 2 secondes.]","Ce soir, il n’y a pas de public ni d’orateurs. Il y a des gens qui sont contents d’être ensemble.","[Pause.]","Faites comme chez vous.","[Souriez. Silence de 2 secondes.]"]}]};
var CSS='.dc-sec{margin:8px 0;border:1px solid rgba(128,128,128,.28);border-radius:16px;padding:0 12px}.dc-sec summary{list-style:none;cursor:pointer;display:flex;flex-wrap:wrap;gap:2px 10px;align-items:baseline;padding:14px 0}.dc-sec summary::-webkit-details-marker{display:none}.dc-sec summary b{font-size:16px}.dc-sec summary span{font-size:12px;opacity:.65}.dc-sec summary small{flex-basis:100%;font-size:13px;opacity:.7}.dc-sec[open] summary{border-bottom:1px solid rgba(128,128,128,.2)}.dc-sec .dc-g{margin:10px 0 14px}.dc-g{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px;margin-top:10px}.dc-c{display:flex;flex-direction:column;gap:6px;text-align:left;font:inherit;color:inherit;background:rgba(128,128,128,.08);border:1px solid rgba(128,128,128,.28);border-radius:16px;padding:14px;cursor:pointer;-webkit-tap-highlight-color:transparent}.dc-c:active{transform:scale(.985)}.dc-c b{font-size:16px;line-height:1.25}.dc-c small{opacity:.75;font-size:13px;line-height:1.35}.dc-c i{font-style:normal;font-size:12px;opacity:.7}.dc-note{font-size:12px;opacity:.65;margin:10px 0 0}'+
'#dcP{position:fixed;inset:0;z-index:100000;background:#000;color:#fff;display:flex;flex-direction:column;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;overscroll-behavior:contain}#dcP *{box-sizing:border-box}#dcP .dc-top{display:flex;align-items:center;gap:10px;padding:max(12px,env(safe-area-inset-top)) max(14px,env(safe-area-inset-right)) 8px max(14px,env(safe-area-inset-left))}#dcP .dc-x{width:44px;height:44px;border-radius:50%;border:1px solid rgba(255,255,255,.25);background:transparent;color:#fff;font-size:20px;cursor:pointer}#dcP .dc-tt{flex:1;min-width:0;font-size:14px;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#dcP .dc-bar{height:3px;background:rgba(255,255,255,.14)}#dcP .dc-bar i{display:block;height:100%;width:0;background:#8fb2ff}#dcP .dc-win{position:relative;flex:1;overflow:hidden;-webkit-mask-image:linear-gradient(transparent 0,#000 16%,#000 78%,transparent 100%);mask-image:linear-gradient(transparent 0,#000 16%,#000 78%,transparent 100%)}#dcP .dc-txt{position:absolute;left:0;right:0;top:0;padding:0 max(22px,env(safe-area-inset-left)) 40vh max(22px,env(safe-area-inset-right));max-width:760px;margin:0 auto;transition:transform .8s cubic-bezier(.3,.7,.2,1);will-change:transform}#dcP .dc-b{margin:0 0 1.05em;font-size:clamp(23px,5.6vw,36px);line-height:1.32;font-weight:600;opacity:.38;transition:opacity .5s,color .5s}#dcP .dc-b.on{opacity:1}#dcP .dc-b.past{opacity:.22}#dcP .dc-b.dir{font-weight:500;font-size:clamp(17px,4.2vw,24px);color:#8fb2ff;font-style:italic}#dcP .dc-ctl{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;padding:10px max(14px,env(safe-area-inset-left)) max(16px,env(safe-area-inset-bottom))}#dcP .dc-btn{min-width:48px;height:48px;padding:0 16px;border-radius:24px;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.06);color:#fff;font:inherit;font-size:15px;cursor:pointer}#dcP .dc-btn.pl{background:#fff;color:#000;font-weight:700;min-width:96px}#dcP .dc-btn.rc.on{background:#c0392b;border-color:#c0392b}#dcP .dc-pill{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);background:rgba(143,178,255,.18);border:1px solid #8fb2ff;color:#cfe0ff;border-radius:20px;padding:8px 16px;font-size:16px;display:none}#dcP .dc-pill.on{display:block}#dcP .dc-ov{position:absolute;inset:0;background:rgba(0,0,0,.94);overflow:auto;padding:max(28px,env(safe-area-inset-top)) 22px 40px;display:flex;flex-direction:column;gap:14px}#dcP .dc-ov>*{max-width:560px;width:100%;margin-left:auto;margin-right:auto}#dcP .dc-ov h2{margin:0;font-size:26px;line-height:1.2}#dcP .dc-ov p{margin:0;line-height:1.5;opacity:.9}#dcP .dc-ov ul{margin:0;padding-left:20px;line-height:1.55}#dcP .dc-ov label{display:flex;gap:10px;align-items:flex-start;line-height:1.45}#dcP .dc-ov input[type=checkbox]{width:22px;height:22px;margin-top:2px;flex:none}#dcP .dc-ov .dc-eb{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#8fb2ff}#dcP audio{width:100%}#dcP .dc-row{display:flex;gap:10px;flex-wrap:wrap}';
var st=document.createElement('style');st.textContent=CSS;document.head.appendChild(st);
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function byId(id){for(var i=0;i<DATA.discours.length;i++)if(DATA.discours[i].id===id)return DATA.discours[i];return null}
function words(s){return (s.trim().match(/\S+/g)||[]).length}
function isDir(l){return l.charAt(0)==='['}
function dirSec(l){var m=/(\d+)\s*seconde/.exec(l);if(m)return +m[1];if(/longue/i.test(l))return 3;if(/pause/i.test(l))return 1.6;if(/respir/i.test(l))return 2.6;return 1.4}
function mins(d){var t=0;d.l.forEach(function(l){t+=isDir(l)?dirSec(l):words(l)/2.2+.4});return Math.max(1,Math.round(t/60*2)/2)}
function fmt(m){return m<1.25?'1 min':(String(m).replace('.',',')+' min')}
function cardsHTML(){
  var h='';DATA.sections.forEach(function(s){var L=DATA.discours.filter(function(d){return d.s===s.id});if(!L.length)return;
    h+='<details class="dc-sec"><summary><b>'+esc(s.t)+'</b><span>'+L.length+' discours</span><small>'+esc(s.d)+'</small></summary><div class="dc-g">'+L.map(function(d){return '<button type="button" class="dc-c" data-disc="'+d.id+'"><i>Niveau '+d.n+' · '+fmt(mins(d))+'</i><b>'+esc(d.t)+'</b><small>'+esc(d.but)+'</small><small>Tu travailles : '+d.appris.map(function(a){return esc(a[0]+' '+a[1])}).join(' · ')+'</small></button>'}).join('')+'</div></details>'});
  return '<section class="dc-all"><h2 style="margin:6px 0 0">Discours à jouer · '+DATA.discours.length+'</h2><p style="margin:4px 0 10px;opacity:.75;font-size:14px">Des discours préparés, un objectif précis chacun, rangés par situation. Le texte défile, les silences sont chronométrés : tu joues le discours à voix haute.</p>'+h+'<p class="dc-note">Textes écrits pour s’entraîner : les noms, lieux et chiffres sont inventés.</p></section>';
}
var P=null;
function close(){if(!P)return;stop();killRec();try{if(P.wl)P.wl.release()}catch(e){}document.removeEventListener('keydown',key);var e=document.getElementById('dcP');if(e)e.remove();P=null}
function key(e){if(!P)return;if(e.key==='Escape')close();else if(e.key===' '&&P.mode==='run'){e.preventDefault();toggle()}else if(e.key==='ArrowLeft')back()}
function el(sel){return document.querySelector('#dcP '+sel)}
function open(id){
  var d=byId(id);if(!d)return;close();
  P={d:d,i:-1,sp:1,mode:'intro',t:0,rec:null,blob:null,chunks:[]};
  var r=document.createElement('div');r.id='dcP';r.setAttribute('role','dialog');r.setAttribute('aria-modal','true');r.setAttribute('aria-label',d.t);
  r.innerHTML='<div class="dc-top"><button class="dc-x" type="button" aria-label="Fermer" data-dc="x">×</button><div class="dc-tt">'+esc(d.t)+'</div></div><div class="dc-bar"><i></i></div><div class="dc-win"><div class="dc-txt">'+d.l.map(function(l,i){return '<p class="dc-b'+(isDir(l)?' dir':'')+'" data-i="'+i+'">'+esc(l)+'</p>'}).join('')+'</div><div class="dc-pill"></div></div><div class="dc-ctl"><button class="dc-btn" type="button" data-dc="back" aria-label="Phrase précédente">⏮</button><button class="dc-btn pl" type="button" data-dc="play">Lecture</button><button class="dc-btn" type="button" data-dc="sp">1×</button><button class="dc-btn rc" type="button" data-dc="rec">● Enregistrer</button></div>';
  document.body.appendChild(r);r.querySelector('.dc-txt').style.paddingTop=Math.round(r.querySelector('.dc-win').clientHeight*.34)+'px';r.addEventListener('click',onClick);document.addEventListener('keydown',key);
  try{if(navigator.wakeLock)navigator.wakeLock.request('screen').then(function(w){if(P)P.wl=w;else w.release()}).catch(function(){})}catch(e){}
  intro();
}
function ov(h){var o=el('.dc-ov');if(o)o.remove();var w=document.createElement('div');w.className='dc-ov';w.innerHTML=h;el('.dc-win').parentNode.appendChild(w);w.style.position='absolute';w.style.zIndex=2;w.style.top=el('.dc-top').offsetHeight+3+'px'}
function intro(){var d=P.d;P.mode='intro';
  ov('<span class="dc-eb">Niveau '+d.n+' · '+fmt(mins(d))+'</span><h2>'+esc(d.t)+'</h2><p><b>Objectif.</b> '+esc(d.but)+'</p><div><b>Ce que tu travailles dans Agora</b><ul>'+d.appris.map(function(a){return '<li>'+esc(a[0]+' · '+a[1])+'</li>'}).join('')+'</ul></div><p>Lis à voix haute. Les lignes en bleu sont des consignes de jeu : respire, marque le silence, regarde quelqu’un. Ne cherche pas à aller vite.</p><div class="dc-row"><button class="dc-btn pl" type="button" data-dc="go">Je suis prêt</button><button class="dc-btn" type="button" data-dc="x">Fermer</button></div>')}
function pill(t){var p=el('.dc-pill');if(!p)return;if(t){p.textContent=t;p.className='dc-pill on'}else p.className='dc-pill'}
function stop(){if(P){clearTimeout(P.tm);clearInterval(P.iv);P.tm=0;P.iv=0}}
function show(i){
  var bs=document.querySelectorAll('#dcP .dc-b');for(var k=0;k<bs.length;k++)bs[k].className='dc-b'+(isDir(P.d.l[k])?' dir':'')+(k<i?' past':'')+(k===i?' on':'');
  var b=bs[i],w=el('.dc-win'),tx=el('.dc-txt');if(b){var y=b.offsetTop-w.clientHeight*.34;tx.style.transform='translateY('+(-Math.max(0,y))+'px)'}
  el('.dc-bar i').style.width=Math.round(100*(i+1)/P.d.l.length)+'%';
}
function dur(i){var l=P.d.l[i];return (isDir(l)?dirSec(l):words(l)/2.2+.4)/P.sp}
function step(i){
  if(!P||P.mode!=='run')return;
  if(i>=P.d.l.length){return end()}
  P.i=i;show(i);var l=P.d.l[i],s=Math.ceil(dur(i));
  if(isDir(l)&&dirSec(l)>=2){var left=Math.round(dirSec(l)/P.sp);pill('Silence · '+left);clearInterval(P.iv);P.iv=setInterval(function(){left--;pill(left>0?'Silence · '+left:'')},1000)}else{pill('');clearInterval(P.iv)}
  clearTimeout(P.tm);P.tm=setTimeout(function(){step(i+1)},dur(i)*1000);
}
function go(){var o=el('.dc-ov');if(o)o.remove();P.mode='run';var b=el('[data-dc="play"]');if(b)b.textContent='Pause';
  var n=3;pill('Prêt · '+n);P.iv=setInterval(function(){n--;if(n>0)pill('Prêt · '+n);else{clearInterval(P.iv);pill('');step(0)}},900)}
function toggle(){
  if(P.mode==='run'){P.mode='pause';stop();pill('');el('[data-dc="play"]').textContent='Reprendre'}
  else if(P.mode==='pause'){P.mode='run';el('[data-dc="play"]').textContent='Pause';step(Math.max(0,P.i))}
  else if(P.mode==='intro')go();else if(P.mode==='end')replay();
}
function back(){if(!P||P.mode==='intro'||P.mode==='end')return;var i=Math.max(0,P.i-(isDir(P.d.l[P.i])?2:1));stop();if(P.mode==='run')step(i);else{P.i=i;show(i)}}
function speed(){P.sp=P.sp===1?1.25:P.sp===1.25?.8:1;el('[data-dc="sp"]').textContent=(P.sp===1?'1':String(P.sp).replace('.',','))+'×'}
function killRec(){try{if(P&&P.rec&&P.rec.state!=='inactive')P.rec.stop()}catch(e){}try{if(P&&P.stream)P.stream.getTracks().forEach(function(t){t.stop()})}catch(e){}if(P){P.rec=null;P.stream=null}}
function rec(){
  var b=el('[data-dc="rec"]');
  if(P.rec){killRec();b.className='dc-btn rc';b.textContent='● Enregistrer';return}
  if(!navigator.mediaDevices||!window.MediaRecorder){pill('Enregistrement indisponible ici');setTimeout(function(){pill('')},2200);return}
  navigator.mediaDevices.getUserMedia({audio:true}).then(function(s){if(!P){s.getTracks().forEach(function(t){t.stop()});return}P.stream=s;P.chunks=[];var r=new MediaRecorder(s);P.rec=r;r.ondataavailable=function(e){if(e.data&&e.data.size)P.chunks.push(e.data)};r.onstop=function(){if(P&&P.chunks.length)P.blob=new Blob(P.chunks,{type:r.mimeType||'audio/webm'})};r.start();b.className='dc-btn rc on';b.textContent='■ Arrêter'}).catch(function(){pill('Micro refusé');setTimeout(function(){pill('')},2200)})
}
function end(){
  P.mode='end';stop();pill('');var d=P.d;if(P.rec)rec();
  el('[data-dc="play"]').textContent='Rejouer';
  setTimeout(function(){var au=P.blob?'<audio controls src="'+URL.createObjectURL(P.blob)+'"></audio>':'';
    ov('<span class="dc-eb">Discours terminé</span><h2>Bien joué.</h2><div><b>Ce que tu viens de travailler</b><ul>'+d.appris.map(function(a){return '<li>'+esc(a[0]+' · '+a[1])+'</li>'}).join('')+'</ul></div><div><b>Coche ce que tu as réussi</b>'+d.controle.map(function(c){return '<label><input type="checkbox"> <span>'+esc(c)+'</span></label>'}).join('')+'</div>'+(au?'<div><b>Ta voix</b>'+au+'</div>':'')+'<div class="dc-row"><button class="dc-btn pl" type="button" data-dc="again">Rejouer</button><button class="dc-btn" type="button" data-dc="x">Fermer</button></div>')},500)
}
function replay(){var o=el('.dc-ov');if(o)o.remove();P.i=-1;P.blob=null;P.mode='run';el('[data-dc="play"]').textContent='Pause';var tx=el('.dc-txt');tx.style.transform='translateY(0px)';step(0)}
function onClick(e){var b=e.target.closest('[data-dc]');if(!b)return;var a=b.getAttribute('data-dc');
  if(a==='x')close();else if(a==='go')go();else if(a==='play')toggle();else if(a==='back')back();else if(a==='sp')speed();else if(a==='rec')rec();else if(a==='again')replay()}
document.addEventListener('click',function(e){var c=e.target.closest&&e.target.closest('[data-disc]');if(c){e.preventDefault();e.stopPropagation();open(c.getAttribute('data-disc'))}},true);
window.AGDISC={cardsHTML:cardsHTML,open:open,close:close,data:DATA};
})();
